DATA.affinity = (function () {
const T = DATA.moveTypes;
const dot = (a, b) => a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
const norm = (a) => Math.sqrt(dot(a, a));
const out = {};
Object.keys(T).forEach((x) => {
out[x] = {};
Object.keys(T).forEach((y) => {
const v = dot(T[x].vec, T[y].vec) / (norm(T[x].vec) * norm(T[y].vec));
out[x][y] = Math.max(0, Math.min(1, v));
});
});
return out;
})();

