DATA.duelStats = function (d) {
const pw = d.power || 6;
return {
maxHp: Math.round(240 + pw * 26), 
atk: Math.round(9 + pw * 1.5),
defLevel: Math.round(5 + pw * 1.05),
speed: Math.round(8 + pw * 0.9)
};
};

